- dashboard { action: string; after?: string; name?: string; pluginKind?: string; position?: number /* integer, >= 0 */; presentation?: "split" | "expanded"; props?: { ... }; size?: "sm" | "md" | "lg" | "xl" | "full"; sizeH?: number /* integer, >= 1, <= 20 */; sizeW?: number /* integer, >= 1, <= 12 */; ... } -> ?
